function isBalanced(text) {
    const pairs = { ")": "(", "]": "[", "}": "{" };
    const stack = [];
    for (const ch of text) {
        if ("([{".includes(ch)) {
            stack.push(ch);
        } else if (ch in pairs) {
            if (stack.pop() !== pairs[ch]) return false;
        }
    }
    return stack.length === 0;
}
console.log(isBalanced("(a + [b * c])"));
console.log(isBalanced("(a + [b * c)]"));
console.log(isBalanced("((a)"));

const back = [];
const forward = [];
let current = "home";
function visit(page) {
    back.push(current);
    current = page;
    forward.length = 0;
}
function goBack() {
    if (back.length > 0) {
        forward.push(current);
        current = back.pop();
    }
}
visit("news");
visit("sport");
goBack();
console.log(current, back, forward);
visit("mail");
console.log(current, back, forward);

