const cart = [];
function addItem(name, price) {
    const found = cart.find((item) => item.name === name);
    if (found) {
        found.qty++;
    } else {
        cart.push({ name, price, qty: 1 });
    }
}
function removeItem(name) {
    const index = cart.findIndex((item) => item.name === name);
